(* [comment removed for export] *)
Lemma aacc_zero (Mx : mem) p g : p mod 8 = 0 -> 0 <= p -> 0 <= g ->
  (forall j, 0 <= j < g -> byte_at Mx (p / 8 + 2147450880 + j) 0) -> aacc Mx p (8 * g).
Proof.
  intros P8 Hp Hg Zg a Ha. left. unfold HeapIfaceA.S, HeapIfaceA.SB.
  pose proof (Z.div_mod p 8 ltac:(Lia.lia)) as DD. rewrite P8, Z.add_0_r in DD.
  assert (E : a / 8 = p / 8 + (a - p) / 8).
  { replace a with ((a - p) + (p / 8) * 8) at 1 by Lia.lia. rewrite Z.div_add by Lia.lia. Lia.lia. }
  rewrite E. replace (p / 8 + (a - p) / 8 + 2147450880) with (p / 8 + 2147450880 + (a - p) / 8) by Lia.lia. apply Zg.
  split; [apply Z.div_pos; Lia.lia| apply Z.div_lt_upper_bound; Lia.lia].
Qed.
Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
