Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.

Theorem reduceD32_ok : PQATSGa.reduceD32_spec L ar HI.
Proof.
  unfold PQATSGa.reduceD32_spec, PQATSG.reduceD32_specG.
  intros fx R M model K LB FF LK Aw cr sp r o fb p w0 w1 HH AM K0 ENT FRM FRS SP16 A10 AO O8 ACC BIG INB ACCp DEFp U0 U8 U16 Hw0 Hw1 BASE KONT.
  destruct ENT as (Rra & RAok & Rsp & Rgp & Rtp & ASTK & STKSH).
  pose proof RAok as (Hr1 & Hr2). pose proof ASTK as (A16 & SLO & SHI & SPT & SDEF & SUP).
  rewrite L5K.rl1 in Rra. rewrite L5K.rl2 in Rsp.
  change (PMSPA.pm_scr PQATSC.RED_H) with 18432 in *.
  pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HH) as (WB & WF & FSAPP & FSCEIL & _).
  assert (SP0 : 0 <= ahl_ceil ar) by (unfold app_mem, FS_BYTES in *; lia).
  (* [comment removed for export] *)
  destruct (WB (p, 64) INB) as ((BR0 & BR1 & BR2 & BR3 & BR4 & BR5) & _ & _ & _ & _ & FA & _). cbn [fst snd] in BR0, BR1, BR2, BR3, BR4, BR5, FA.
  assert (P8 : p mod 8 = 0) by (clear - BR2; pose proof (Z.div_mod p 16 ltac:(Lia.lia)) as Dp; rewrite BR2, Z.add_0_r in Dp; rewrite Dp; replace (16 * (p / 16)) with ((2 * (p / 16)) * 8) by Lia.lia; apply Z_mod_mult).
  assert (BIGp : 2147446784 + 17592186048512 <= p \/ p + 64 <= 2147446784) by (destruct BR5 as (_ & Y & _); unfold BIGSHADOW_LO, BIGSHADOW_HI in Y; clear - Y; Lia.lia).
  assert (Hp : 4096 <= p <= 140737488355264) by (clear - BR0 BR4 SLO SPT; Lia.lia).
  assert (DPo : p + 64 <= o \/ o + 32 <= p).
  { destruct AO as (f & Hf & Z1 & Z2). destruct (FA f ltac:(apply in_or_app; left; exact Hf)) as [Y|Y]; clear - Y Z1 Z2; Lia.lia. }
  assert (DPs : sp - 16 + 16 <= p \/ p + 64 <= sp - 16) by (right; clear - BR4 SLO; Lia.lia).
  (* [comment removed for export] *)
  pose proof (PMASK.mach_vis L ar C HI LY HIok _ FF LK cr Aw M model HH BASE) as (VM0 & VSB & VUAR).
  destruct (PQAKR3.obj_pf L ar C HI LY HIok LB FF LK cr Aw M model o 32 HH AO O8 ltac:(lia) eq_refl) as ((OA1 & OA2 & OA3 & OA4) & OAV & ODEF & OAZ).
  specialize (OAZ ACC). change (32 / 8) with 4 in OAZ.
  pose proof (PQAKR3.stk_w_vis L ar C HI LY HIok LB FF LK cr Aw M model sp 18432 (sp - 16) 16 HH ASTK ltac:(lia) ltac:(lia) ltac:(lia)) as SW.
  set (H := ahid Aw model) in *. set (MV := mrestrict H M) in *.
  assert (WO : L5.writable RSEGS MV o 32).
  { apply (proj2 (L5A.writable_vis H M o 32 OAV ltac:(lia) ltac:(lia))). apply (L5C.writable_of_defined RSEGS M o 32 ODEF); lia. }
  pose proof BIG as (Bfb & Bfr & Blen & Bt1 & B16 & B24 & REST). cbn [L5.bo_fb L5.bo_len L5.bo_st Z.of_nat Pos.of_succ_nat Pos.succ] in Bfb, Bfr, Blen, Bt1, B16, B24, REST.
  assert (VFB : L5.u8_at RSEGS MV o fb) by (apply (proj2 (L5A.u8_at_vis H M o fb (L5A.avis_sub H o 32 o 1 OAV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia))); exact Bfb).
  assert (VLEN : L5.u64_at RSEGS MV (o + 8) 3) by (apply (PQAKR3.word_vis Aw model M (o + 8) _ (L5A.avis_sub H o 32 (o + 8) 8 OAV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) Blen)).
  assert (V24 : L5.u64_at RSEGS MV (o + 24) p) by (apply (PQAKR3.word_vis Aw model M (o + 24) _ (L5A.avis_sub H o 32 (o + 24) 8 OAV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) B24)).
  assert (Hfb : 0 <= fb <= 255) by (clear - Bfr; Lia.lia).
  pose proof (L5SAR.vis_pack L ar C HI LYa HIok _ FF LK cr Aw M model HH) as (_ & _ & _ & _ & VBLK & _).
  assert (PV : L5A.avis H p 64) by (apply (VBLK p 64 p 64); [exact INB| lia| lia]).
  assert (PW : L5.writable RSEGS MV p 64).
  { apply (proj2 (L5A.writable_vis H M p 64 PV ltac:(clear - BR0; Lia.lia) ltac:(clear - BR4 SLO SPT; Lia.lia))). apply (L5C.writable_of_defined RSEGS M p 64 DEFp); clear - BR0 BR4 SLO SPT; Lia.lia. }
  pose proof (PMKA.blk_shadow_vis L ar C HI LYa HIok _ FF LK cr Aw M model p 64 p 64 HH INB ltac:(lia) ltac:(lia) P8 ltac:(lia) eq_refl ACCp) as PSHZ.
  change (64 / 8) with 8 in PSHZ. fold H in PSHZ. fold MV in PSHZ.
  assert (V8p : L5.u64_at RSEGS MV (p + 8) w1) by (apply (PQAKR3.word_vis Aw model M (p + 8) _ (L5A.avis_sub H p 64 (p + 8) 8 PV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) U8)).
  assert (V16p : L5.u64_at RSEGS MV (p + 16) 0) by (apply (PQAKR3.word_vis Aw model M (p + 16) _ (L5A.avis_sub H p 64 (p + 16) 8 PV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) U16)).
  assert (Hw1' : 1 <= w1 <= 18446744073709551615) by (clear - Hw1; Lia.lia).
  assert (AL16 : PQATGP5.aligned sp 16) by (unfold PQATGP5.aligned; exact SP16).
  assert (AL8 : PQATGP5.aligned o 8) by (unfold PQATGP5.aligned; exact O8).
  assert (ALp : PQATGP5.aligned p 16) by (unfold PQATGP5.aligned; exact BR2).
  assert (Hsp : 140735332487184 <= sp <= 140737488355328) by (clear - SLO SHI SPT SP0; Lia.lia).
  assert (DSo : sp - 16 + 16 <= o \/ o + 32 <= sp - 16) by (right; clear - OA2 SLO; Lia.lia).
  assert (Ho : 7036928 <= o <= 140737488355296) by (clear - OA1 OA3; Lia.lia).
  LeanFeed.pfeed ident:(P) (PQATGP5.qgd3_conc fx R MV (fun j => match j with 2%nat => sp | 33%nat => o | 37%nat => w1 | 38%nat => fb | 40%nat => p | _ => 0 end)) ltac:(first [assumption | exact Rsp | exact A10 | lia]).
  destruct P as (fx1 & R1 & M1v & MG1 & _ & FRZ1 & MS1 & KS1 & _ & _ & _ & _ & _ & _ & _ & _ & _ & Clen).
  assert (R1ra : getr R1 (reg 1) = Z_to_bv 64 r) by (rewrite (KS1 1%nat) by inl; exact Rra).
  pose proof (PMK.ret_to RSEGS fx1 R1 M1v 0xcae8c W_cae3c r F_cae3c eq_refl D_cae3c R1ra ltac:(lia) Hr2) as MS2.
  unfold PMSPA.cfg.
  apply (L5SAR.apiece L ar C HI LYa HIok LB FF LK cr Aw M model fx fx1 R 0xcad98 R1 r M1v (fun a => sp - 8 <= a < sp \/ o + 8 <= a < o + 16) K HH AM).
  { eapply msteps_trans; [exact MS1| exact MS2]. }
  { exact MG1. }
  { intros a Ha N. apply FRZ1; [exact Ha| clear - N; Lia.lia| clear - N; Lia.lia]. }
  { intros a Ha Wa. split; [| clear - Wa Hsp Ho; Lia.lia]. destruct Wa as [Wa|Wa].
    - unfold aclientw, aclient_g. right; left. split; [clear - Wa Hsp SLO SHI SPT; Lia.lia| intros X; clear - X Wa; Lia.lia].
    - destruct AO as (f & Hf & Hf1 & Hf2). destruct f as ((Ff & kf) & rsf). cbn [ff_addr ff_class fst snd] in Hf1, Hf2.
      apply (L5SAR.fframe_client L ar LB FF 0 0 Ff kf rsf a Hf). clear - Wa Hf1 Hf2; Lia.lia. }
  intros M1 model1 HH1 AM1 MRT1 HID1 VIS1 MGM1 FR1 VV1.
  assert (EK0 : L5SAR.ek L ar LB FF sp 18432 [(o + 8, 8)] M M1).
  { apply (L5SAR.ek_piece L ar LB FF sp 18432 [(o + 8, 8)] M M1 (fun a => sp - 8 <= a < sp \/ o + 8 <= a < o + 16)).
    { intros a Ha N. apply FR1; [exact Ha| exact N]. }
    intros a Ha Hc Hout X. destruct X as [X|X].
    - destruct (L5SAR.aclient_cases L ar C HI LYa HIok LB FF LK cr Aw M (vml_of model) sp 18432 a HH SPT Hc) as [(Y1 & Y2)|Y]; [apply Y2; clear - X; Lia.lia| clear - X Y SLO; Lia.lia].
    - apply (Hout (o + 8, 8)); [left; reflexivity| unfold L5.in_rng; cbn [fst snd]; clear - X; Lia.lia]. }
  assert (AVo : L5A.avis H o 32) by exact OAV. assert (VIS1' : mrestrict H M1 = M1v) by exact VIS1.
  apply (KONT fx1 R1 M1 model1 LK).
  - apply L5SAR.preserved_by_index. intros k Hk. apply KS1. revert k Hk. apply (L5K.incl_b L5SAR.cs_all PQATGP5.KS_qgd3). vm_compute. reflexivity.
  - unfold L5.big_at. cbn [L5.bo_fb L5.bo_len L5.bo_st Z.of_nat Pos.of_succ_nat Pos.succ].
    split; [apply (L5C.u8_at_agree RSEGS M M1 o fb); [intros i Hi; apply FR1; [clear - Hi Ho; Lia.lia| clear - Hi DSo; Lia.lia]| lia| lia| exact Bfb]|].
    split; [exact Bfr|].
    split; [apply (proj1 (L5A.u64_at_vis H M1 (o + 8) _ (L5A.avis_sub H o 32 (o + 8) 8 AVo ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia))); rewrite VIS1'; exact Clen|].
    split; [exact Bt1|].
    split; [apply (L5C.u64_at_agree RSEGS M M1 (o + 16) 8); [intros i Hi; apply FR1; [clear - Hi Ho; Lia.lia| clear - Hi DSo; Lia.lia]| lia| lia| exact B16]|].
    split; [apply (L5C.u64_at_agree RSEGS M M1 (o + 24) p); [intros i Hi; apply FR1; [clear - Hi Ho; Lia.lia| clear - Hi DSo; Lia.lia]| lia| lia| exact B24]|].
    split; [clear; Lia.lia|]. exact (proj2 REST).
  - apply (L5SAR.ahpres_of L ar LB FF sp 18432 [(o + 8, 8)] M M1 EK0).
    + intros i Hi. apply MGM1. apply SDEF. exact Hi.
    + apply (L5SAR.dk_grows L ar LB FF sp 18432 M M1 MGM1).
  - exact MRT1.
  - intros x Hx. exact Hx.
  - exact AM1.
  - exact HH1.
Qed.
