Section Frame.
Variables (F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp SCR spc (sp - 72) sp OC OWN F fl 1 LK2 M2 model2 cr BX0.
Hypothesis APART : forall a n0 sp0 scr0, (forall i0, 0 <= i0 < n0 -> aclient L ar (BX0 ++ LBX) FF sp0 scr0 (a + i0)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes 1 <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes 1 / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Local Notation FF' := ((F, 1, spc + 32) :: FF).
Local Notation GM := (PQAKR3.g_mem L ar HI M model LBX FF LK Aw sp PQATSG.RUP_H W spc OWN 1 F).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PQATSG.RUP_H BX0 W HH AM K0 ENT FRM FRS Hh2 wappW spc (sp - 72) sp OC OWN 1 F fl LK2 M2 model2 G APART HSPCf) (at level 10, f at level 9, only parsing).

Ltac pf BIx :=
  destruct ((GF PQAKR3.g_pfacts) _ _ _ _ _ _ BIx) as ((PF1 & PF2 & PF3 & PF4 & _) & (FD & FW & FSW & FLU & FLW) & (PL1 & PL2 & PL3 & PL4) & (SW & OWNV & PS1 & PS2 & PS3 & PS4) & (CSB & CUAR & IMGC) & (AVSH & AVF & AVS));
  change (ff_bytes 1) with 128 in *; change (128 / 8) with 16 in *.

