Lemma FIN M6 model6 LK6 (fx6 : FPState) R6 :
  GM BX0 M6 model6 LK6 Aw cr ->
  getr R6 (reg 2) = Z_to_bv 64 spc -> getr R6 (reg 3) = getr R (reg 3) -> getr R6 (reg 4) = getr R (reg 4) ->
  getr R6 (reg 24) = getr R (reg 24) -> getr R6 (reg 25) = getr R (reg 25) -> getr R6 (reg 26) = getr R (reg 26) -> getr R6 (reg 27) = getr R (reg 27) ->
  getr R6 (reg 8) = Z_to_bv 64 sp -> getr R6 (reg 18) = Z_to_bv 64 F -> getr R6 (reg 19) = Z_to_bv 64 i -> getr R6 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R6 (reg 23) = Z_to_bv 64 F ->
