Let HIokF (D : list (list Z)) : HAJ.asan_iface_okR L ar C SCFG (HIk D) := HAR.fr_base L ar C SCFG LR HIk FAMok D.
Let AE := PQATAE.areserve3_ok L ar C LR HIk LY FAMok.

Theorem reserve3_ok : PQATSGa.reserve3_spec L ar HIk LR.
Proof.
