Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (p : Z) (gk : list Z),
    regs_preserved R R' -> In gk GKEYS ->
    L5.big_at RSEGS M' o (L5.BO (Z.lor fb 1) 3%nat (L5.BDyn 8 p)) ->
    L5.u64_at RSEGS M' p v0 -> L5.u64_at RSEGS M' (p + 8) v1 -> L5.u64_at RSEGS M' (p + 16) 0 ->
    L5CA.afresh L ar LBX (FF ++ LK') M' p 64 ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    PMSP.credit_keep cr cr' (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv (HIk (gk :: D)) ((p, 64) :: LBX) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

