Lemma MSET (gk : list Z) (p : Z) M5 model5 LK5 Aw5 cr5 (fx5 : FPState) R5 :
  In gk GKEYS -> GM [gk :: D] [(p, 64)] M5 model5 LK5 Aw5 cr5 ->
  ablock_range L ar p 64 -> blocks_apart p 64 LBX -> fframes_apart p 64 (FF' ++ LK5) -> L5.defined M5 p 64 -> shadow_blk M5 p 64 ->
  PMSP.credit_keep cr cr5 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  L5.big_at RSEGS M5 o (L5.BO (Z.lor fb 1) 3%nat (L5.BDyn 8 p)) ->
  L5.u64_at RSEGS M5 p v0 -> L5.u64_at RSEGS M5 (p + 8) v1 ->
  getr R5 (reg 1) = Z_to_bv 64 RETIRE -> getr R5 (reg 10) = Z_to_bv 64 (p + 16) -> getr R5 (reg 11) = Z_to_bv 64 0 -> getr R5 (reg 12) = Z_to_bv 64 8 ->
  getr R5 (reg 2) = Z_to_bv 64 spc -> getr R5 (reg 3) = getr R (reg 3) -> getr R5 (reg 4) = getr R (reg 4) -> getr R5 (reg 27) = getr R (reg 27) ->
  getr R5 (reg 8) = Z_to_bv 64 sp -> getr R5 (reg 18) = Z_to_bv 64 F -> getr R5 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 23) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 MSPC M5 model5) K.
Proof.
