Lemma BODY2 (gk : list Z) (p : Z) M4 model4 LK4 Aw4 cr4 (fx4 : FPState) R4 :
  In gk GKEYS -> GM [gk :: D] [(p, 64)] M4 model4 LK4 Aw4 cr4 ->
  ablock_range L ar p 64 -> blocks_apart p 64 LBX -> fframes_apart p 64 (FF' ++ LK4) -> L5.defined M4 p 64 -> shadow_blk M4 p 64 ->
  PMSP.credit_keep cr cr4 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  L5.big_at RSEGS M4 o (L5.BO (Z.lor fb 1) 2%nat (L5.BDyn 8 p)) ->
  L5.u64_at RSEGS M4 p v0 -> L5.u64_at RSEGS M4 (p + 8) v1 ->
  getr R4 (reg 2) = Z_to_bv 64 spc -> getr R4 (reg 3) = getr R (reg 3) -> getr R4 (reg 4) = getr R (reg 4) -> getr R4 (reg 27) = getr R (reg 27) ->
  getr R4 (reg 8) = Z_to_bv 64 sp -> getr R4 (reg 18) = Z_to_bv 64 F -> getr R4 (reg 22) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R4 (reg 23) = Z_to_bv 64 F ->
  getr R4 (reg 19) = Z_to_bv 64 3 -> getr R4 (reg 20) = Z_to_bv 64 o -> getr R4 (reg 21) = Z_to_bv 64 (o + 8) -> getr R4 (reg 24) = Z_to_bv 64 2147450880 ->
  getr R4 (reg 25) = Z_to_bv 64 2 -> getr R4 (reg 26) = Z_to_bv 64 ((o + 8) / 8 + 2147450880) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 RA_RSV M4 model4) K.
Proof.
