Module PQATCM2.
Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Abbreviation mem := (word -> option byte).

Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.


Theorem cmp21i_ok : PQATSC4a.cmp21i_spec L ar HI.
Proof.
  unfold PQATSC4a.cmp21i_spec, PQATSC4.cmp21i_specG.
  intros fx R M model K LB FF LK Aw cr sp r x y fbx fby x0 x1 y0 y1 HH AM K0 ENT FRM FRS SP16 A10 A11 AOx X8 ACCx BINx Tx1 AOy Y8 ACCy BINy Ty1 BASE KONT.
  destruct ENT as (Rra & RAok & Rsp & Rgp & Rtp & ASTK & STKSH).
  pose proof RAok as (Hr1 & Hr2). pose proof ASTK as (A16 & SLO & SHI & SPT & SDEF & SUP).
  rewrite L5K.rl1 in Rra. rewrite L5K.rl2 in Rsp.
  change (PMSPA.pm_scr PQATSC.CMP_H) with 18432 in *.
  pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HH) as (WB & WF & FSAPP & FSCEIL & _).
  assert (SP0 : 0 <= ahl_ceil ar) by (unfold app_mem, FS_BYTES in *; lia).
  pose proof (PMASK.mach_vis L ar C HI LY HIok _ FF LK cr Aw M model HH BASE) as (VM0 & VSB & VUAR).
  destruct (PQAKR3.obj_pf L ar C HI LY HIok LB FF LK cr Aw M model x 32 HH AOx X8 ltac:(lia) eq_refl) as ((OX1 & OX2 & OX3 & OX4) & OXV & OXDEF & OXZ).
  specialize (OXZ ACCx). change (32 / 8) with 4 in OXZ.
  destruct (PQAKR3.obj_pf L ar C HI LY HIok LB FF LK cr Aw M model y 32 HH AOy Y8 ltac:(lia) eq_refl) as ((OY1 & OY2 & OY3 & OY4) & OYV & OYDEF & OYZ).
  specialize (OYZ ACCy). change (32 / 8) with 4 in OYZ.
  pose proof (PQAKR3.stk_w_vis L ar C HI LY HIok LB FF LK cr Aw M model sp 18432 (sp - 16) 16 HH ASTK ltac:(lia) ltac:(lia) ltac:(lia)) as SW.
  set (H := ahid Aw model) in *. set (MV := mrestrict H M) in *.
  assert (WX : L5.writable RSEGS MV x 32).
  { apply (proj2 (L5A.writable_vis H M x 32 OXV ltac:(lia) ltac:(lia))). apply (L5C.writable_of_defined RSEGS M x 32 OXDEF); lia. }
  pose proof BINx as ((Bfb & Bfr & Blen & Bt0 & B16 & _ & _ & _ & _) & Bx0 & _). cbn [L5.bo_fb L5.bo_len L5.bo_st] in Bfb, Bfr, Blen, Bt0, B16.
  pose proof BINy as ((Cfb & Cfr & Clen & Ct0 & C16 & _ & _ & _ & _) & By0 & _). cbn [L5.bo_fb L5.bo_len L5.bo_st] in Cfb, Cfr, Clen, Ct0, C16.
  assert (VFBx : L5.u8_at RSEGS MV x fbx) by (apply (proj2 (L5A.u8_at_vis H M x fbx (L5A.avis_sub H x 32 x 1 OXV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia))); exact Bfb).
  assert (VLENx : L5.u64_at RSEGS MV (x + 8) 2) by (apply (PQAKR3.word_vis Aw model M (x + 8) _ (L5A.avis_sub H x 32 (x + 8) 8 OXV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) Blen)).
  assert (VFBy : L5.u8_at RSEGS MV y fby) by (apply (proj2 (L5A.u8_at_vis H M y fby (L5A.avis_sub H y 32 y 1 OYV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia))); exact Cfb).
  assert (VLENy : L5.u64_at RSEGS MV (y + 8) 1) by (apply (PQAKR3.word_vis Aw model M (y + 8) _ (L5A.avis_sub H y 32 (y + 8) 8 OYV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) Clen)).
  assert (V16y : L5.u64_at RSEGS MV (y + 16) y0) by (apply (PQAKR3.word_vis Aw model M (y + 16) _ (L5A.avis_sub H y 32 (y + 16) 8 OYV ltac:(lia) ltac:(lia)) ltac:(lia) ltac:(lia) C16)).
  assert (AL16 : PQATC4P1.aligned sp 16) by exact SP16. assert (ALx : PQATC4P1.aligned x 8) by exact X8. assert (ALy : PQATC4P1.aligned y 8) by exact Y8.
  assert (Hy0 : 0 <= y0 < 2 ^ 64) by lia. assert (Hfbx : 0 <= fbx < 2 ^ 64) by lia. assert (Hfby : 0 <= fby < 2 ^ 64) by lia.
  assert (APx : sp - 16 + 16 <= x \/ x + 32 <= sp - 16) by (right; lia). assert (APy : sp - 16 + 16 <= y \/ y + 32 <= sp - 16) by (right; lia).
  LeanFeed.pfeed ident:(P) (PQATC4P1.qrcI_conc fx R MV (fun j => match j with 2%nat => sp | 33%nat => x | 37%nat => y0 | 38%nat => fbx | 39%nat => y | 41%nat => fby | _ => 0 end)) ltac:(first [assumption | exact Rsp | exact A10 | exact A11 | lia]).
  destruct P as (fx9 & R9 & M9v & MG9 & _ & FRZ9 & MS9 & KS9 & U10 & _).
  assert (R9ra : getr R9 (reg 1) = Z_to_bv 64 r) by (rewrite (KS9 1%nat) by inl; exact Rra).
  pose proof (PMK.ret_to RSEGS fx9 R9 M9v 0xcc34c W_cc2fc r F_cc2fc eq_refl D_cc2fc R9ra ltac:(lia) Hr2) as MSr.
  unfold PMSPA.cfg.
  apply (L5SAR.apiece L ar C HI LYa HIok LB FF LK cr Aw M model fx fx9 R 0xcc1d8 R9 r M9v (fun a => sp - 8 <= a < sp) K HH AM).
  { eapply msteps_trans; [exact MS9| exact MSr]. }
  { exact MG9. }
  { intros a Ha N. apply FRZ9; [exact Ha| lia]. }
  { intros a Ha Wa. split; [| lia]. unfold aclientw, aclient_g. right; left. split; [lia| intros X; lia]. }
  intros M1 model1 HH1 AM1 MRT1 HID1 VIS1 MGM1 FR1 VV1.
  assert (EK0 : L5SAR.ek L ar LB FF sp 18432 [] M M1).
  { apply (L5SAR.ek_piece L ar LB FF sp 18432 [] M M1 (fun a => sp - 8 <= a < sp)).
    { intros a Ha N. apply FR1; [exact Ha| exact N]. }
    intros a Ha Hc Ho X. destruct (L5SAR.aclient_cases L ar C HI LYa HIok LB FF LK cr Aw M (vml_of model) sp 18432 a HH SPT Hc) as [(Y1 & Y2)|Y]; [apply Y2; lia| lia]. }
  apply (KONT fx9 R9 M1 model1 LK).
  - apply L5SAR.preserved_by_index. intros k Hk. apply KS9. unfold L5SAR.cs_all in Hk. repeat (destruct Hk as [<-|Hk]; [inl|]). destruct Hk.
  - exact U10.
  - apply (L5SAR.ahpres_of L ar LB FF sp 18432 [] M M1 EK0).
    + intros i Hi. apply MGM1. apply SDEF. exact Hi.
    + apply (L5SAR.dk_grows L ar LB FF sp 18432 M M1 MGM1).
  - exact MRT1. - intros q Hq; exact Hq. - exact AM1. - exact HH1.
Qed.
End WithHeap.
End PQATCM2.

