  getr R5 (reg 19) = Z_to_bv 64 o -> getr R5 (reg 20) = Z_to_bv 64 (o + 8) -> getr R5 (reg 21) = Z_to_bv 64 2147450880 -> getr R5 (reg 24) = Z_to_bv 64 (o2 + 16) ->
  getr R5 (reg 25) = Z_to_bv 64 (Z.of_nat leny) -> getr R5 (reg 26) = Z_to_bv 64 (o / 8 + 2147450880) -> getr R5 (reg 27) = Z_to_bv 64 ((o + 8) / 8 + 2147450880) ->
