    regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o -> In gk GKEYS ->
    lo + 2 ^ 64 * hi = x0 + 2 ^ 64 * x1 + y0 -> PQATSG.ws_this_atA RSEGS M' o (PQATSG.WDyn (Z.lor fbx 1) p lo hi) ->
    L5CA.afresh L ar LBX (FF ++ LK') M' p 64 ->
    L5CA.ahpres L ar LBX FF sp SCR W M M' ->
    PMSP.credit_keep cr cr' (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv (HIk (gk :: D)) (PQATSG.ws_own (PQATSG.WDyn (Z.lor fbx 1) p lo hi) ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.
