(* [comment removed for export] *)
Lemma TAIL M2 model2 LK2 (fx2 : FPState) (R2 : bvmap 5 word) :
  mm M2 model2 LK2 -> PQATSW2.bdyn_at RSEGS M2 o fb len p v0 v1 ->
  getr R2 (reg 2) = Z_to_bv 64 spc -> getr R2 (reg 8) = Z_to_bv 64 o ->
  (forall k, In k [3; 4; 23; 24; 25; 26; 27]%nat -> getr R2 (reg k) = getr R (reg k)) ->
